{
  "title": "Is the new checkout button really better?",
  "setting": "Day 3 at Aurora Shop, Chicago",
  "mission": "Decide whether version B of the checkout button really sells more, and tell the team what you **can and cannot** conclude from the test so far.",
  "deadline": "Launch decision meeting today at 3:30 p.m.",
  "panels": [
    {
      "title": "A/B test on the checkout button",
      "metrics": [
        {
          "label": "Version A (blue)",
          "value": "4.0%",
          "note": "Visitors who bought · 1,000 visitors"
        },
        {
          "label": "Version B (green)",
          "value": "4.6%",
          "note": "Visitors who bought · 1,000 visitors"
        },
        {
          "label": "Gap",
          "value": "0.6 points",
          "note": "B looks better by 15% in relative terms"
        }
      ],
      "note": "Live for 3 days · about 1,000 visitors per version so far"
    }
  ],
  "team": [
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Wants to ship the green button fast; cares about the holiday sales plan and the team's time.",
      "ai": false
    },
    {
      "id": "data",
      "role": "Data analyst",
      "expertise": "Knows the test method well and wants to check the numbers before anyone trusts them.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Runs checks and calculations on the test data when asked.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of a wrong launch",
      "start": 50,
      "goodWhen": "low"
    },
    {
      "id": "speed",
      "label": "Time to launch",
      "start": 60,
      "goodWhen": "low"
    }
  ],
  "skills": [
    {
      "id": "real-diff",
      "name": "Tell a real difference from chance",
      "practice": "Write down two groups' rates and ask whether the gap could show up by luck with the same sample sizes, in about 5 minutes."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "Pick a test length in advance for one real comparison in your life, and write down how many visitors or people you need per group."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one test result to a friend who isn't a data person in one sentence, without the word p-value."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "Green is up 15 percent after three days. Holiday traffic starts next week, so I want to ship it to everyone today."
        },
        {
          "from": "data",
          "text": "Three days and about 1,000 visitors each is a small sample. A gap that size could still come from luck."
        }
      ],
      "prompt": "What do you do before the 3:30 p.m. meeting?",
      "choices": [
        {
          "id": "ship-now",
          "text": "Tell {{product}} the green button wins and agree to ship it today.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "Great, I'll tell the team it's live. Thanks for moving fast."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 35
            },
            {
              "meter": "speed",
              "change": -40
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "real-diff",
              "kind": "improve",
              "text": "A 0.6-point gap on about 1,000 visitors per version can easily be chance. You shipped before checking that.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Calling green the winner without a range of possible results gave the team more certainty than the data holds.",
              "example": "\"Green is ahead, but the test is too small to be sure yet.\""
            }
          ],
          "next": "ending-shipped"
        },
        {
          "id": "ask-ai",
          "text": "Ask the AI assistant to check whether the gap could be chance at this sample size.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "Using a standard two-proportion test: A is 40 of 1,000 and B is 46 of 1,000. The p-value is about 0.47, and the 95% range for the gap is about -1.0 to +2.2 points. The data fits no difference at all."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "speed",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "real-diff",
              "kind": "good",
              "text": "You checked whether the gap could be chance before trusting it. That is the core move of a hypothesis test.",
              "example": null
            },
            {
              "skill": "sample",
              "kind": "good",
              "text": "You asked how big the test needed to be, not just whether green was ahead.",
              "example": null
            }
          ],
          "next": "sample-size"
        },
        {
          "id": "wait-full",
          "text": "Tell {{product}} you'll recommend waiting for the test to finish, without running any checks first.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "Fine, but I'm not happy about losing the holiday window. Get me a real answer by the meeting."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "speed",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You chose to wait instead of acting on three days of data.",
              "example": null
            },
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Saying wait without a reason leaves the team with no plan. Say what result would settle it.",
              "example": "\"Let's run until each version has about 8,000 visitors, then decide.\""
            }
          ],
          "next": "sample-size"
        }
      ]
    },
    {
      "id": "sample-size",
      "messages": [
        {
          "from": "data",
          "text": "Before we decide how long to run this, we need to know how many visitors each version needs to reliably catch a gap this small."
        },
        {
          "from": "product",
          "text": "Can't we just run it another week and call it?"
        }
      ],
      "prompt": "How do you set the test length?",
      "choices": [
        {
          "id": "fixed-plan",
          "text": "Ask the AI assistant to estimate how many visitors per version a 0.6-point gap needs, then run until you reach that number.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "To reliably detect a gap from 4.0% to 4.6% with 80% power, you need about 18,000 visitors per version. At about 1,000 per version per 3 days, that is roughly 54 days."
            }
          ],
          "effects": [
            {
              "meter": "speed",
              "change": -20
            },
            {
              "meter": "risk",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You set the sample size before reading more results, which keeps you from stopping early when the number looks good.",
              "example": null
            }
          ],
          "next": "ending-wait"
        },
        {
          "id": "one-week",
          "text": "Agree to run one more week and decide then, without a target number.",
          "quality": "fair",
          "replies": [
            {
              "from": "product",
              "text": "Good. We'll look again next Friday."
            }
          ],
          "effects": [
            {
              "meter": "speed",
              "change": -10
            },
            {
              "meter": "risk",
              "change": -5
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "A/B test on the checkout button",
              "metrics": [
                {
                  "label": "Version A (blue)",
                  "value": "4.1%",
                  "note": "Visitors who bought · 2,500 visitors"
                },
                {
                  "label": "Version B (green)",
                  "value": "4.5%",
                  "note": "Visitors who bought · 2,500 visitors"
                },
                {
                  "label": "Gap",
                  "value": "0.4 points",
                  "note": "Still small and uncertain"
                }
              ],
              "note": "Live for 10 days · about 2,500 visitors per version"
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "Running another week without a target means you could keep looking until something seems to win. Set the number first.",
              "example": "\"We'll run until each version has about 18,000 visitors.\""
            }
          ],
          "next": "ending-wait"
        }
      ]
    },
    {
      "id": "ending-shipped",
      "messages": [],
      "prompt": "",
      "choices": []
    }
  ],
  "endings": [
    {
      "id": "ending-shipped",
      "outcome": "Green went live to everyone. The gap was 0.6 points on small samples. Within a month, sales were flat to slightly down, and the team had to explain the change to leadership."
    },
    {
      "id": "ending-wait",
      "outcome": "The test ran to its planned size. Green finished at 4.4% and blue at 4.1%, a gap that is not clearly above chance, so the team kept blue and tested a bigger change next."
    }
  ],
  "summary": [
    "A gap between two groups can be chance, so check it against the sample size before you trust it.",
    "Set how many visitors or people you need before the test starts, so you do not stop early because the number looks good.",
    "Explain a result by saying what it shows and how uncertain it is, not just which version is ahead."
  ]
}

{
  "title": "E se a luz chegasse em goles, não em jatos?",
  "setting": "Uma tarde de sol em Curitiba",
  "mission": "Você tem um painel de LED, uma lanterna e um interruptor com regulador de brilho. Decida como testar se a luz chega em **pacotes mínimos**, como goles, ou em qualquer quantidade, como um jato contínuo.",
  "deadline": null,
  "panels": [],
  "team": [
    {
      "id": "ana",
      "role": "Professora de física",
      "expertise": "Conhece a história da luz e gosta de experimentos simples em casa.",
      "ai": false
    },
    {
      "id": "lucas",
      "role": "Colega de bancada",
      "expertise": "Entende de eletrônica e quer resolver rápido, com o que estiver à mão.",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "clareza",
      "label": "Clareza da ideia",
      "start": 20,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "pacotes",
      "name": "Explicar que a energia vem em pacotes",
      "practice": "Explique, em uma frase, por que um pacote mínimo de luz é diferente de um jato contínuo, usando a analogia de goles de água."
    },
    {
      "id": "dualidade",
      "name": "Reconhecer a dualidade onda-partícula",
      "practice": "Diga em duas frases quando a luz se comporta como onda e quando se comporta como partícula, dando um exemplo de cada."
    }
  ],
  "startNodeId": "d1",
  "nodes": [
    {
      "id": "d1",
      "messages": [
        {
          "from": "lucas",
          "text": "Pensei em algo bem simples: se a luz vier em goles, ao diminuir o brilho ela deveria sumir em degraus, não de forma suave."
        },
        {
          "from": "ana",
          "text": "Boa ideia para começar. Mas antes de testar, precisamos decidir o que seria diferente se a luz fosse um jato contínuo."
        }
      ],
      "prompt": "Como você começa o teste?",
      "choices": [
        {
          "id": "degraus",
          "text": "Você pensa no que cada hipótese preveria e escolhe um experimento que mostre degraus ou não.",
          "quality": "strong",
          "replies": [
            {
              "from": "ana",
              "text": "Isso! Se a luz vem em goles, algo deveria mudar em saltos, e não de forma contínua."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": 25
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "good",
              "text": "Você começou pela previsão de cada hipótese, antes de mexer no aparelho.",
              "example": null
            }
          ],
          "next": "d2"
        },
        {
          "id": "brilho",
          "text": "Você varia o brilho do LED o máximo que puder e observa o que acontece.",
          "quality": "fair",
          "replies": [
            {
              "from": "lucas",
              "text": "Legal, mas sem saber o que esperar, fica difícil dizer se algo estranho apareceu."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "improve",
              "text": "Observar é bom, mas antes escreva o que cada ideia preveria. Assim o teste responde uma pergunta.",
              "example": "\"Se a luz vem em goles, eu espero saltos no brilho.\""
            }
          ],
          "next": "d2"
        },
        {
          "id": "pesquisa",
          "text": "Você decide que é melhor só ler sobre o assunto e confiar no que os livros dizem.",
          "quality": "weak",
          "replies": [
            {
              "from": "ana",
              "text": "Ler ajuda, mas a ideia só fica sua quando você mesmo a testa ou imagina o teste."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade",
              "kind": "improve",
              "text": "Ler sem testar deixa a ideia de pacotes abstrata. Tente imaginar um teste simples antes de buscar mais texto.",
              "example": null
            }
          ],
          "next": "d2"
        }
      ]
    },
    {
      "id": "d2",
      "messages": [
        {
          "from": "lucas",
          "text": "Agora surgiu uma dúvida: a luz às vezes se espalha como ondas na água, e às vezes bate em um ponto como bolinhas. Qual é a verdade?"
        },
        {
          "from": "ana",
          "text": "Essa é a dualidade onda-partícula. A luz não escolhe um papel; ela mostra um ou outro conforme o experimento."
        }
      ],
      "prompt": "Como você explica o comportamento da luz para {{lucas}}?",
      "choices": [
        {
          "id": "contexto",
          "text": "Você diz que a luz age como onda em alguns experimentos e como partícula em outros, e dá um exemplo de cada.",
          "quality": "strong",
          "replies": [
            {
              "from": "lucas",
              "text": "Entendi. Então ela é as duas coisas, dependendo de como a gente olha?"
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": 20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade",
              "kind": "good",
              "text": "Você mostrou que a luz tem os dois comportamentos e deu exemplos concretos.",
              "example": null
            }
          ],
          "next": "fim-ok"
        },
        {
          "id": "simples",
          "text": "Você diz que a luz é uma onda e pronto, sem falar do comportamento de partícula.",
          "quality": "fair",
          "replies": [
            {
              "from": "lucas",
              "text": "Mas e as bolinhas que você mencionou? Não batem com isso."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "dualidade",
              "kind": "improve",
              "text": "Uma explicação só de onda deixa de fora parte do que foi observado. Inclua as duas faces.",
              "example": "\"Em alguns testes a luz se espalha como onda; em outros, chega em pontos como partículas.\""
            }
          ],
          "next": "fim-meio"
        },
        {
          "id": "mistura",
          "text": "Você fala que a luz é um tipo de bolinha pequena que às vezes fica de lado.",
          "quality": "weak",
          "replies": [
            {
              "from": "ana",
              "text": "Cuidado, essa imagem confunde mais do que ajuda. A luz não é bolinha no sentido comum."
            }
          ],
          "effects": [
            {
              "meter": "clareza",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "pacotes",
              "kind": "improve",
              "text": "Analogias ajudam, mas precisam ser precisas. Diga que a energia chega em pacotes, sem comparar a luz com objetos comuns.",
              "example": "\"A energia da luz chega em pacotes mínimos, chamados quanta.\""
            }
          ],
          "next": "fim-meio"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "fim-ok",
      "outcome": "Você e {{lucas}} montaram um teste claro e entenderam que a luz se comporta como onda ou partícula conforme o experimento. A energia chega em pacotes mínimos, os quanta."
    },
    {
      "id": "fim-meio",
      "outcome": "A ideia ficou meio certa: vocês perceberam que a luz tem dois comportamentos, mas a explicação ficou incompleta. Uma revisão rápida com {{ana}} resolve isso."
    }
  ],
  "summary": [
    "A energia da luz e da matéria chega em pacotes mínimos chamados quanta, não em qualquer quantidade.",
    "A luz se comporta como onda em alguns experimentos e como partícula em outros: as duas faces são reais.",
    "Antes de testar uma ideia, escreva o que cada hipótese preveria para que o experimento responda uma pergunta."
  ]
}

{
  "title": "Essa dose está certa?",
  "setting": "Plantão noturno, enfermaria de clínica médica",
  "mission": "Antes de administrar a amoxicilina ao paciente, você precisa **confirmar a dose calculada pelo peso e a unidade da prescrição**, e decidir o que fazer se algo não bater.",
  "deadline": "Próxima administração às 23h00, pela prescrição vigente",
  "panels": [
    {
      "title": "Prescrição e paciente",
      "metrics": [
        {
          "label": "Peso registrado",
          "value": "32 kg",
          "note": "Pesado na internação, há 2 dias"
        },
        {
          "label": "Prescrição",
          "value": "50 mg/kg/dia",
          "note": "Dividido em 3 doses (a cada 8 horas)"
        },
        {
          "label": "Concentração do frasco",
          "value": "250 mg/5 mL",
          "note": "Suspensão oral"
        },
        {
          "label": "Dose prescrita por tomada",
          "value": "400 mg",
          "note": "Escrita pelo médico na prescrição"
        }
      ],
      "note": "Conferência de rotina às 22h40 · paciente com infecção respiratória, pediatria de 9 anos"
    }
  ],
  "team": [
    {
      "id": "colega",
      "role": "Enfermeira de referência",
      "expertise": "Conhece a rotina da enfermaria e quer fechar a medicação no horário sem atrasos.",
      "ai": false
    },
    {
      "id": "medico",
      "role": "Médico plantonista",
      "expertise": "Prescreveu a medicação e conhece o quadro clínico, mas está atendendo outra intercorrência.",
      "ai": false
    },
    {
      "id": "ia",
      "role": "Assistente de IA",
      "expertise": "Faz cálculos e confere contas e unidades quando você pede; não decide a dose nem assina nada.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risco",
      "label": "Risco de erro na dose",
      "start": 30,
      "goodWhen": "low"
    },
    {
      "id": "atraso",
      "label": "Atraso na medicação",
      "start": 0,
      "goodWhen": "low"
    }
  ],
  "skills": [
    {
      "id": "calc",
      "name": "Calcular dose por peso",
      "practice": "Calcule, em papel, a dose de um medicamento para uma criança de 20 kg com prescrição de 40 mg/kg/dia em 2 tomadas, e confira a unidade antes de dizer o resultado em voz alta."
    },
    {
      "id": "conferir",
      "name": "Conferir a prescrição",
      "practice": "Escreva, em uma linha, o peso, a dose por kg, a concentração e o volume a administrar de uma prescrição que você conferiu hoje, sem olhar para a folha depois."
    },
    {
      "id": "duvida",
      "name": "Comunicar uma dúvida ao médico",
      "practice": "Diga em uma frase a um colega: 'Estou com a dose X, o peso é Y, a conta dá Z; você confirma?', e treine essa frase três vezes em voz alta."
    }
  ],
  "startNodeId": "conferir-peso",
  "nodes": [
    {
      "id": "conferir-peso",
      "messages": [
        {
          "from": "colega",
          "text": "Você já vai dar a amoxicilina? A família está perguntando quando o remédio chega, e estou atrasada na troca de soro do leito 4."
        },
        {
          "from": "ia",
          "text": "Posso fazer a conta quando você quiser. Diga os dados que você está usando."
        }
      ],
      "prompt": "Antes de qualquer coisa, o que você faz primeiro?",
      "choices": [
        {
          "id": "calcular-sozinha",
          "text": "Faço a conta de cabeça rapidamente e, se bater com a prescrição, sigo.",
          "quality": "fair",
          "replies": [
            {
              "from": "colega",
              "text": "Ótimo, então pode seguir. Só me avisa quando terminar."
            }
          ],
          "effects": [
            {
              "meter": "risco",
              "change": 10
            },
            {
              "meter": "atraso",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "calc",
              "kind": "improve",
              "text": "Uma conta de cabeça é fácil de errar com miligramas e mililitros. Vale escrever cada passo.",
              "example": "Escrevo: 50 mg × 32 kg = 1.600 mg/dia; ÷ 3 = 533 mg por tomada; então comparo com os 400 mg prescritos."
            }
          ],
          "next": "conferir-dose"
        },
        {
          "id": "pesar-dados",
          "text": "Confiro o peso registrado e a dose por kg antes de calcular qualquer coisa.",
          "quality": "strong",
          "replies": [
            {
              "from": "ia",
              "text": "Certo. Quer que eu faça o cálculo completo com os dados da prescrição?"
            }
          ],
          "effects": [
            {
              "meter": "risco",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "conferir",
              "kind": "good",
              "text": "Você começou pelo peso e pela dose por quilo, que são a base de qualquer cálculo pediátrico.",
              "example": null
            }
          ],
          "next": "conferir-dose"
        },
        {
          "id": "pedir-peso",
          "text": "Assumo que o peso está certo, porque foi pesado na internação, e vou direto ao frasco.",
          "quality": "weak",
          "replies": [
